import{z as A,x as B,o as n,c as p,q as r,j as o,D as s,d as t,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"半同步复制","description":"","frontmatter":{"title":"半同步复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/semi-sync-replication.md","filePath":"cs/semi-sync-replication.md","lastUpdated":1791413859000}'),d={name:"cs/semi-sync-replication.md"};function c(m,a,D,f,C,T){const E=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=r('<h1 id="半同步复制" tabindex="-1">半同步复制 <a class="header-anchor" href="#半同步复制" aria-label="Permalink to &quot;半同步复制&quot;">​</a></h1><div class="epigraph"><p>提交返回前至少一备库收到日志：RPO 相对异步收紧，延迟相对全同步放松。仍可能在窗口里丢，合同要写「几个 ACK」。</p><footer>—— 据 Gray 复制；MySQL 半同步；Postgres 同步复制级别</footer></div><p><a href="/cs/logical-replication-cdc">上一课</a>把流送给异构下游。本课回到同构 HA：异步复制 RPO 大（主挂丢未传送日志）；全同步每备都 fsync 则延迟差。半同步（semi-sync）：等待 \\(k\\) 个备库 ACK（常 \\(k{=}1\\)）再让提交返回。持久性等级课的③/④ 落地。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ACK 语义：收到内存 vs 已 fsync，差一档 RPO。缺口是<strong>主挂时选谁</strong>：已 ACK 的备库有提交，未 ACK 的可能落后——升主要选最前，并处理裂脑。半同步在备库全挂时的降级：等还是退异步，上一课 D 等级已问。</p><p>性能：提交延迟 ≈ 组提交 + 网络 RTT + 备库刷盘。跨 AZ 明显。组提交窗口可等一批一起发，与半同步叠加。</p><p><span class="marginnote">术语翻译：ACK 有两档含义——「收到内存」是备库把日志放进接收缓冲就算数，备库机器若此时断电就丢；「已 fsync」是日志真正写到盘上，断电也不丢。合同写「k 个 ACK」时若不写档位，RPO 完全是两个等级。</span></p><p><span class="marginnote">数字实例：本地组提交加 fsync 约 1 ms；跨可用区 RTT 常到 1-2 ms、备库 fsync 再 1 ms——半同步把每次提交从约 1 ms 拉到约 3-4 ms，对每秒上万次提交的库就是吞吐掉一档的量级。</span></p><p><span class="marginnote">MySQL after_sync/after_commit 差异是产品坑。Postgres <code>synchronous_commit</code> 与 <code>synchronous_standby_names</code>。本课 k-ACK 机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置 k 与名单。监控复制延迟、ACK 超时。超时降级要告警。只读备库可异步，不进 k。</p><p>与 2PC：半同步不是跨分片原子，只是单主日志的耐久扩展。跨分片仍 2PC 或 Calvin。</p>',12)),(n(),o(l,null,{default:s(()=>[i(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COM%5B%22%E4%B8%BB%20commit%20%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20SEND%5B%22%E4%BC%A0%20WAL%22%5D%0A%20%20SEND%20--%3E%20ACK%5B%22k%20%E4%B8%AA%E5%A4%87%E5%BA%93%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20ACK%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A%20%20FAIL%5B%22%E5%A4%87%E5%BA%93%E5%85%A8%E8%B6%85%E6%97%B6%22%5D%20--%3E%20POL%5B%22%E9%99%8D%E7%BA%A7%E6%88%96%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"乱序：备库 apply 可落后于收到；若 ACK 只表示收到，升主后还要 apply 完才服务——RTO 含追平。若 ACK=apply+fsync，延迟更大、RTO 更干净。",-1)),a[5]||(a[5]=e("p",null,"脑裂：旧主复活仍接写，需 fencing（STONITH、时间线 id）。后课分布式会再遇。",-1)),a[6]||(a[6]=e("p",null,"上面那张图回答「一次提交怎么等 ACK」；下面这张回答主挂之后的事——升主不是随便挑一台，选错备库会把已 ACK 的提交丢掉。",-1)),(n(),o(l,null,{default:s(()=>[i(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%BB%E5%BA%93%E5%AE%95%E6%9C%BA%22%5D%20--%3E%20B%5B%22%E6%94%B6%E9%9B%86%E5%90%84%E5%A4%87%E5%BA%93%E6%97%A5%E5%BF%97%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%80%89%E6%9C%80%E5%89%8D%E7%9A%84%E5%B7%B2%20ACK%20%E5%A4%87%E5%BA%93%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8F%90%E5%8D%87%E4%B8%BA%E6%96%B0%E4%B8%BB%22%5D%0A%20%20D%20--%3E%20E%5B%22fencing%20%E6%97%A7%E4%B8%BB%3A%20STONITH%20%E6%88%96%E6%97%B6%E9%97%B4%E7%BA%BF%22%5D%0A%20%20D%20--%3E%20F%5B%22%E8%90%BD%E5%90%8E%E5%A4%87%E5%BA%93%E8%BF%BD%E5%B9%B3%E6%97%A5%E5%BF%97%22%5D%0A%20%20F%20--%3E%20G%5B%22%E9%87%8D%E6%96%B0%E5%8A%A0%E5%85%A5%20k%20%E5%90%8D%E5%8D%95%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：fencing 是给旧主发一张「通行证作废令」——STONITH（Shoot The Other Node In The Head）干脆直接断它的电。宁可旧主彻底缺席，也不能让它带着过期数据继续接客；「我还没死」的旧主比「已死」的更危险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不量化读己之写的会话粘滞——下一课。也不把仲裁多数派当半同步（那是共识）。Spanner 后课。</p><p>后课默认：要小 RPO 用 k-ACK 同步复制；要低延迟用异步并接受丢失窗口。复制延迟与读己之写：会话读备库看见旧值。</p><p>半同步收紧的是提交日志的故障域，不是隔离级别。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>k 个备库 ACK 再返回，RPO/延迟可调。</li><li>ACK 是收到还是 fsync 必须写清；降级要告警。</li><li>复制延迟与读己之写下一课。</li><li>出处：Gray；MySQL/Postgres 同步复制。</li></ul>',7))])}const _=A(d,[["render",c]]);export{u as __pageData,_ as default};
